sql.ahj.hoa.link.add:

INSERT INTO brs.ahj_utility_link (ahj_utility_id, name, link, username, password, notes, date_created, created_by_id, date_modified, modified_by_id, link_type_id)
VALUES (:ahjUtilityId, :name, :link, :username, :password, :notes, now(), :currentUser, now(), :currentUser, :linkTypeId)
RETURNING id;
